/**
 * The main session's context size, as the statusline last measured it: `used_tokens` in
 * `<config>/.cache/context-<session_id>.json`. The reader for the hooks that act on a large context
 * (done-claim's /clear hand-off).
 *
 * `LARGE_CONTEXT` is the token count from which a session counts as large: `CLAUDE_LARGE_CONTEXT`
 * (a positive number) or 120 000.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const path = require('path');
const { CACHE_DIR, readJson } = require('./cache');

const DEFAULT_LARGE_CONTEXT = 120_000;
const override = Number(process.env.CLAUDE_LARGE_CONTEXT);
const LARGE_CONTEXT = Number.isFinite(override) && override > 0 ? override : DEFAULT_LARGE_CONTEXT;
/** A snapshot older than this belongs to a session that stopped rendering: do not trust it. */
const SNAPSHOT_MAX_AGE_MS = 6 * 60 * 60 * 1000;

/** The session's `used_tokens`, or null: bad id, no snapshot, a stale one, or no finite count in it. */
function contextTokens(sessionId, now = Date.now()) {
  if (typeof sessionId !== 'string' || !/^[\w-]{1,128}$/.test(sessionId)) return null;
  const snapshot = readJson(path.join(CACHE_DIR, `context-${sessionId}.json`));
  if (!Number.isFinite(snapshot?.at) || now - snapshot.at > SNAPSHOT_MAX_AGE_MS) return null;
  return Number.isFinite(snapshot.used_tokens) ? snapshot.used_tokens : null;
}

module.exports = { contextTokens, LARGE_CONTEXT };
